package cn.tbforum.security;
import cn.tbforum.repo.UserRepository; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Configuration @EnableWebSecurity public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain security(HttpSecurity http, JwtService jwt, UserRepository users) throws Exception { return http.cors(c->{}).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).headers(h->h.contentTypeOptions(co->{}).frameOptions(fo->fo.deny()).httpStrictTransportSecurity(hsts->hsts.includeSubDomains(true).maxAgeInSeconds(31536000)).contentSecurityPolicy(csp->csp.policyDirectives("default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; img-src 'self' data: blob:; connect-src 'self' ws: wss:; font-src 'self' https://fonts.gstatic.com"))).authorizeHttpRequests(a->a.requestMatchers(org.springframework.http.HttpMethod.GET,"/api/forums/**","/api/posts/**","/api/tags/**","/api/search").permitAll().requestMatchers(org.springframework.http.HttpMethod.GET,"/api/users/*","/api/users/search","/api/users/*/followers","/api/users/*/following").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/api/auth/register","/api/auth/login","/api/auth/forgot-password","/api/auth/reset-password").permitAll().requestMatchers("/actuator/health","/actuator/info","/actuator/prometheus","/error","/","/index.html","/assets/**","/uploads/**","/ws/**","/rss.xml","/sitemap.xml","/robots.txt","/global","/profile","/search","/forum/**","/tag/**","/post/**","/u/**").permitAll().anyRequest().authenticated()).exceptionHandling(e->e.authenticationEntryPoint((q,res,ex)->{res.setStatus(org.springframework.http.HttpStatus.UNAUTHORIZED.value());res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"code\":\"UNAUTHENTICATED\",\"message\":\"请先登录\"}");})).addFilterBefore(new JwtFilter(jwt,users),UsernamePasswordAuthenticationFilter.class).build(); }
 @Bean org.springframework.web.servlet.config.annotation.WebMvcConfigurer staticResources(){return new org.springframework.web.servlet.config.annotation.WebMvcConfigurer(){@Override public void addResourceHandlers(org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations("file:uploads/");}};}
 @Bean CorsConfigurationSource corsConfigurationSource(){var c=new CorsConfiguration();c.setAllowedOriginPatterns(List.of("http://localhost:*","http://127.0.0.1:*","http://192.168.*:*","http://10.*:*","http://172.16.*:*"));c.setAllowedMethods(List.of("GET","POST","PATCH","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",c);return source;}
 static class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(JwtFilter.class); JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException { String h=r.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String token=h.substring(7);if(!token.isBlank())try{var u=users.findByUsername(jwt.subject(token)).orElse(null);if(u!=null){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.username,null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+u.role))));}else{reject(s,"登录用户不存在，请重新登录");return;}}catch(JwtException e){log.warn("JWT 验证失败: {}",e.getMessage());reject(s,"登录已失效，请重新登录");return;}} c.doFilter(r,s); } private void reject(HttpServletResponse s,String msg)throws IOException{s.setStatus(org.springframework.http.HttpStatus.UNAUTHORIZED.value());s.setContentType("application/json;charset=UTF-8");s.getWriter().write("{\"code\":\"INVALID_TOKEN\",\"message\":\""+msg+"\"}");} }
}
